const epic_result_t *epic_result(void *context) {
    collector_t *c = (collector_t *)context;
    if (!c) {
        return NULL;
    }
    fill_state(c, c->res.state);
    c->res.buffer = buffer_digest(c);
    sha_final(&c->sha, c->res.sha);
    c->res.packets = c->packets;
    c->res.bytes = c->bytes;
    c->res.snap_count = c->snap_count;
    c->res.trace_count = c->trace_count;
    c->res.snaps = c->snaps;
    c->res.trace = c->trace;
    return &c->res;
}

uint64_t epic_sizeof_result(void) {
    return (uint64_t)sizeof(epic_result_t);
}
